function escapeDollarNumber(text: string): string {
  let isInCode = false;
  return text.split('\n').map(line => {
    if (line.trim() === '```' || line.trim() === '`') {
      isInCode = !isInCode;
      return line;
    }
    if (!isInCode) {
      return line.replace(/(?<!`.*|\\)\$\d+([,.](\d+[,.])?\d+)?(?!.*\$\B)(?!.*`)/g, '\\$&');
    } else {
      return line;
    }
  }).join('\n');
}
