```ts
/**
 * Sorts an array of models based on specified rules.
 *
 * @param models - The array of models to be sorted.
 * @param rule - The sorting rule to apply.
 *   - "custom-first": Custom models will be sorted first.
 *   - "default-first": Default models will be sorted first.
 *
 * @returns The sorted array of models.
 */
const sortModelTable = (
  models: ReturnType<typeof collectModels>,
  rule: "custom-first" | "default-first",
) =>
  models.sort((a, b) => {
    // Determine if the models are custom
    let aIsCustom = a.provider?.providerType === "custom";
    let bIsCustom = b.provider?.providerType === "custom";

    // If one is custom while another isn't, sort by `custom`
    if (aIsCustom !== bIsCustom) {
      return aIsCustom === (rule === "custom-first") ? -1 : 1;
    }

    // Sort by providerType and model_name
    if (a.provider && b.provider) {
      const providerTypeComparison = a.provider.providerType.localeCompare(b.provider.providerType);
      if (providerTypeComparison !== 0) {
        return providerTypeComparison;
      }
      return a.name.localeCompare(b.name);
    }

    // If one of the providers is undefined, sort based on the availability of the provider
    if (a.provider && !b.provider) {
      return -1;
    }
    if (!a.provider && b.provider) {
      return 1;
    }

    // If both providers are undefined, sort by model_name
    return a.name.localeCompare(b.name);
  });
