```typescript
export function semverCompare(a: string, b: string): -1 | 0 | 1 {
  const parse = (v: string): { major: number, minor: number, patch: number, prerelease: string, buildmetadata: string } => {
    const match = v.match(/^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-.]+))?(?:\+([0-9A-Za-z-]+))?$/);
    if (!match) throw new Error(`Invalid semantic version: ${v}`);
    return {
      major: parseInt(match[1], 10),
      minor: parseInt(match[2], 10),
      patch: parseInt(match[3], 10),
      prerelease: match[4] || '',
      buildmetadata: match[5] || ''
    };
  };

  const compareNumeric = (x: number, y: number): -1 | 0 | 1 => x === y ? 0 : x < y ? -1 : 1;
  const comparePrerelease = (x: string, y: string): -1 | 0 | 1 => {
    if (x === y) return 0;
    if (!x) return 1;
    if (!y) return -1;
    const xParts = x.split('.');
    const yParts = y.split('.');
    const len = Math.max(xParts.length, yParts.length);
    for (let i = 0; i < len; i++) {
      const xPart = xParts[i];
      const yPart = yParts[i];
      if (xPart === undefined) return -1;
      if (yPart === undefined) return 1;
      if (xPart === yPart) continue;
      const xNum = parseInt(xPart, 10);
      const yNum = parseInt(yPart, 10);
      if (isNaN(xNum) && isNaN(yNum)) return xPart.localeCompare(yPart);
      if (isNaN(xNum)) return -1;
      if (isNaN(yNum)) return 1;
      return compareNumeric(xNum, yNum);
    }
    return 0;
  };

  const va = parse(a);
  const vb = parse(b);

  for (const part of ['major', 'minor', 'patch'] as const) {
    const comp = compareNumeric(va[part], vb[part]);
    if (comp !== 0) return comp;
  }

  return comparePrerelease(va.prerelease, vb.prerelease);
}
```

This refactored version:
1. Validates input strings as valid semantic versions.
2. Properly parses version strings into their components.
3. Implements a comparison algorithm that follows semver rules, including proper handling of pre-release versions.
