        const midX = (nextPoint[0] + x) / 2;
        ctx.quadraticCurveTo(
          nextPoint[0],
          centerY - (nextPoint[1] - centerY),
          midX,
          centerY - ((nextPoint[1] + y) / 2 - centerY),
