class ResponseAnimator {
  private responseText = '';
  private remainText = '';
  private finished = false;

  constructor(
    private readonly onUpdate: (text: string, delta: string) => void,
    private readonly controller: AbortController
  ) {}

  animate() {
    if (this.finished || this.controller.signal.aborted) {
      this.responseText += this.remainText;
      return this.responseText;
    }

    if (this.remainText.length > 0) {
      const fetchCount = Math.max(1, Math.round(this.remainText.length / 60));
      const fetchText = this.remainText.slice(0, fetchCount);
      this.responseText += fetchText;
      this.remainText = this.remainText.slice(fetchCount);
      this.onUpdate(this.responseText, fetchText);
    }

    requestAnimationFrame(() => this.animate());
  }

  addText(text: string) {
    this.remainText += text;
  }

  finish() {
    this.finished = true;
    return this.responseText + this.remainText;
  }
}
